WITH with_latest AS (SELECT s.*, x.inventory_quantity, x.inventory_last_restock FROM stores s LEFT JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock AS inventory_last_restock FROM inventory c WHERE c.store_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT DATE_TRUNC('WEEK', inventory_last_restock) AS week_start, DATE_TRUNC('MONTH', inventory_last_restock) AS activity_month, COUNT(*) FILTER (WHERE city = 'Tokyo') AS tokyo_rows, SORT_ARRAY(COLLECT_SET(region)) AS region_list, PERCENTILE_APPROX(sqft, 0.9) AS sqft_p90, GROUPING_ID() AS grouping_level FROM with_latest GROUP BY CUBE (DATE_TRUNC('WEEK', inventory_last_restock), DATE_TRUNC('MONTH', inventory_last_restock));
